import cv2,numpy as np
im=cv2.imread('first_frame.png')[:,:,::-1].astype(float)
# radial edge support all centers/r
best=[]
for cx in range(140,154):
 for cy in range(94,108):
  for r in range(11,19):
   vals=[]
   for a in np.linspace(0,2*np.pi,180,endpoint=False):
    x=int(round(cx+r*np.cos(a))); y=int(round(cy+r*np.sin(a)))
    if 1<=x<255 and 1<=y<143:
     vals.append(np.abs(im[y,x]-im[y,x-1]).mean()+np.abs(im[y,x]-im[y-1,x]).mean())
   best.append((np.mean(vals),cx,cy,r))
print(sorted(best,reverse=True)[:30])
